mapper.select:
SELECT

FROM
iot_device_event
WHERE
del_flag = '0'

    AND device_id = #{event.deviceId}


    AND device_code = #{event.deviceCode}


    AND product_id = #{event.productId}


    AND identifier = #{event.identifier}


    AND name LIKE CONCAT('%', #{event.name}, '%')


    AND event_type = #{event.eventType}


    AND factory_code = #{event.factoryCode}

ORDER BY event_time DESC
